package android.graphics.drawable;import android.graphics.*;import android.graphics.drawable.shapes.Shape;public class ShapeDrawable extends Drawable {public final Shape shape;private final Paint paint=new Paint();public ShapeDrawable(Shape s){shape=s;}public Paint getPaint(){return paint;}public void draw(Canvas c){rv.batch.Platform.invoke("drawable.shape",this,c);}public void setAlpha(int a){paint.setAlpha(a);}public void setColorFilter(ColorFilter f){paint.setColorFilter(f);}public int getOpacity(){return PixelFormat.TRANSLUCENT;}}
